import{_ as t,o as a,c as o,a3 as i}from"./chunks/framework.D1iekJsc.js";const m=JSON.parse('{"title":"Agnes AI","description":"Agnes AI free multimodal API — site entry, Free Access keys, text/image/video model lists, and how to fill them in MiniTavern.","frontmatter":{"title":"Agnes AI","description":"Agnes AI free multimodal API — site entry, Free Access keys, text/image/video model lists, and how to fill them in MiniTavern.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Agnes AI · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Agnes AI free multimodal API — site entry, Free Access keys, text/image/video model lists, and how to fill them in MiniTavern."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/free-cloud/agnes-ai"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/free-cloud/agnes-ai"}]]},"headers":[],"relativePath":"en/free-cloud/agnes-ai.md","filePath":"en/free-cloud/agnes-ai.md","lastUpdated":1787224147000}'),n={name:"en/free-cloud/agnes-ai.md"};function r(s,e,d,l,g,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="agnes-ai" tabindex="-1">Agnes AI <a class="header-anchor" href="#agnes-ai" aria-label="Permalink to &quot;Agnes AI&quot;">​</a></h1><p>Multimodal models from Singapore Sapiens AI: one OpenAI-compatible gateway for <strong>text chat, image gen, and video</strong>. <strong>Free Access</strong> suits chatting and trying image gen without a paid Key; quotas and rate limits follow the console.</p><h2 id="sites-and-entry-points" tabindex="-1">Sites and entry points <a class="header-anchor" href="#sites-and-entry-points" aria-label="Permalink to &quot;Sites and entry points&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>International</td><td><a href="https://agnes-ai.com/" target="_blank" rel="noreferrer">agnes-ai.com</a></td></tr><tr><td>China</td><td><a href="https://agnes-ai.cn/" target="_blank" rel="noreferrer">agnes-ai.cn</a></td></tr><tr><td>API console (sign-up / Key)</td><td><a href="https://platform.agnes-ai.com/" target="_blank" rel="noreferrer">platform.agnes-ai.com</a></td></tr><tr><td>Developer docs</td><td><a href="https://agnes-ai.com/en/docs/overview" target="_blank" rel="noreferrer">agnes-ai.com/en/docs/overview</a></td></tr><tr><td>Model catalog (GitHub)</td><td><a href="https://github.com/AgnesAI-Labs/AgnesAI-Models" target="_blank" rel="noreferrer">AgnesAI-Labs/AgnesAI-Models</a></td></tr><tr><td>API Base URL</td><td><code>https://apihub.agnes-ai.com/v1</code></td></tr></tbody></table><p>Pick international or China by region; <strong>API Key and Base URL follow whatever the console / docs show now</strong>.</p><h2 id="how-to-get-free-access" tabindex="-1">How to get Free Access <a class="header-anchor" href="#how-to-get-free-access" aria-label="Permalink to &quot;How to get Free Access&quot;">​</a></h2><ol><li>Open <a href="https://platform.agnes-ai.com/" target="_blank" rel="noreferrer">platform.agnes-ai.com</a>, register and sign in (usually email; whether a card is required follows the page).</li><li>Developer console → <strong>API Keys</strong> → create and copy the Key (often starts with <code>sk-</code>).</li><li>In MiniTavern use <strong>Custom (OpenAI)</strong> (chat) or <strong>Custom (OpenAI Images)</strong> (image gen) with Base URL + Key — see below.</li></ol><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Free path</td><td><strong>Free Access</strong>: core Flash series callable for free (RPM / fair-use limits); good for personal trials and demos</td></tr><tr><td>Paid upgrade</td><td><strong>Token Plan</strong>: higher TPS / monthly quota for production and high-frequency agents (optional)</td></tr><tr><td>Free-tier rate limits (reference)</td><td>Text ~<strong>20 RPM</strong>; image gen by resolution (~20 RPM at 1K, stricter higher); video ~<strong>1 RPM</strong> (official <a href="https://agnes-ai.com/en/docs/tokenplan" target="_blank" rel="noreferrer">Token Plan FAQ</a>)</td></tr><tr><td>Card required</td><td>Free Access usually not; consider Token Plan for commercial use or higher limits</td></tr></tbody></table><blockquote><p>Policies change. If the console says a model needs Token Plan, or you get 429, trust the site and your account permissions.</p></blockquote><h2 id="model-list" tabindex="-1">Model list <a class="header-anchor" href="#model-list" aria-label="Permalink to &quot;Model list&quot;">​</a></h2><p>Common IDs from public docs and the catalog (<strong>case-sensitive</strong>). Flash is usually free; <strong>Pro</strong> is generally paid inference.</p><h3 id="text-chat-vision-understanding" tabindex="-1">Text (chat / vision understanding) <a class="header-anchor" href="#text-chat-vision-understanding" aria-label="Permalink to &quot;Text (chat / vision understanding)&quot;">​</a></h3><p>Chat Completions: <code>POST /v1/chat/completions</code>. In MiniTavern pick <strong>Custom (OpenAI)</strong>.</p><table tabindex="0"><thead><tr><th>Model ID</th><th>Notes</th></tr></thead><tbody><tr><td><code>agnes-2.5-flash</code></td><td>Recommended: chat, coding, tool use, multi-turn and image understanding; ~512K context</td></tr><tr><td><code>agnes-2.0-flash</code></td><td>Previous Flash, fallback</td></tr><tr><td><code>agnes-2.5-pro</code> / <code>agnes-2.5-pro-alpha</code></td><td>Paid reasoning (advanced coding / science, etc.) — <strong>not free</strong></td></tr></tbody></table><h3 id="images-text-to-image-image-to-image" tabindex="-1">Images (text-to-image / image-to-image) <a class="header-anchor" href="#images-text-to-image-image-to-image" aria-label="Permalink to &quot;Images (text-to-image / image-to-image)&quot;">​</a></h3><p>Images API: both text-to-image and image-to-image use <code>POST /v1/images/generations</code> (image-to-image puts <code>image</code> in the body — <strong>not</strong> OpenAI <code>/images/edits</code>). In MiniTavern pick <strong>Custom (OpenAI Images)</strong>, same Base URL <code>https://apihub.agnes-ai.com/v1</code>; the App routes custom protocol this way, and Test with a reference image also hits generations.</p><table tabindex="0"><thead><tr><th>Model ID</th><th>Notes</th></tr></thead><tbody><tr><td><code>agnes-image-2.1-flash</code></td><td>Recommended: dense image gen and edit, flexible sizes</td></tr><tr><td><code>agnes-image-2.0-flash</code></td><td>Text-to-image / image-to-image; URL or Base64 output</td></tr></tbody></table><h3 id="video-text-to-video-image-to-video" tabindex="-1">Video (text-to-video / image-to-video) <a class="header-anchor" href="#video-text-to-video-image-to-video" aria-label="Permalink to &quot;Video (text-to-video / image-to-video)&quot;">​</a></h3><p>Videos: <code>POST /v1/videos</code> (async). Common IDs:</p><table tabindex="0"><thead><tr><th>Model ID</th><th>Notes</th></tr></thead><tbody><tr><td><code>agnes-video-v2.0</code></td><td>Text-to-video, image-to-video, multi-image / keyframes, etc.</td></tr><tr><td><code>agnes-video-v2.5</code> (or Video 2.5 in docs)</td><td>Newer video API — see <a href="https://agnes-ai.com/en/docs/agnes-video-v20" target="_blank" rel="noreferrer">official video docs</a></td></tr></tbody></table><p>MiniTavern <strong>has no built-in video generation entry</strong> yet; the table is for comparing site capabilities. For chat and image gen, start with Flash text / image models.</p><h2 id="how-to-fill-in-minitavern" tabindex="-1">How to fill in MiniTavern <a class="header-anchor" href="#how-to-fill-in-minitavern" aria-label="Permalink to &quot;How to fill in MiniTavern&quot;">​</a></h2><p>General steps: <a href="/ultra_guides/en/manual/model-link">Model link</a>.</p><h3 id="chat" tabindex="-1">Chat <a class="header-anchor" href="#chat" aria-label="Permalink to &quot;Chat&quot;">​</a></h3><p>Path: <strong>Settings → Models → Model link → New</strong></p><ol><li>Platform: <strong>Custom (OpenAI)</strong></li><li>Base URL: <code>https://apihub.agnes-ai.com/v1</code></li><li>Paste API Key</li><li>Model ID: <code>agnes-2.5-flash</code> (or another text model from the console list)</li><li><strong>Test</strong> → on success, set as default</li></ol><h3 id="image-gen" tabindex="-1">Image gen <a class="header-anchor" href="#image-gen" aria-label="Permalink to &quot;Image gen&quot;">​</a></h3><p>Path: <strong>Settings → Image gen → Image gen link</strong></p><ol><li>Platform: <strong>Custom (OpenAI Images)</strong></li><li>Same Base URL</li><li>Same Key; model e.g. <code>agnes-image-2.1-flash</code></li><li>Test, then use <code>/imagine</code> or image-gen entries</li></ol><p>Chat and image links can differ: e.g. chat on <code>agnes-2.5-flash</code>, images on <code>agnes-image-2.1-flash</code>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/ultra_guides/en/free-cloud/">Free cloud overview</a> — other vendors’ free / trial quotas</li><li><a href="/ultra_guides/en/free-cloud/#free-image-generation">Free image gen</a></li><li><a href="/ultra_guides/en/manual/model-link">Model link</a></li><li><a href="/ultra_guides/en/local/image-gen/">Image model deploy</a> — local A1111 / ComfyUI</li></ul>',32)])])}const u=t(n,[["render",r]]);export{m as __pageData,u as default};
